import React, { useState, useEffect, useRef } from "react";
import emailjs from "@emailjs/browser";
import "./brutalist-button.css";


/* ================= MAIN APP ================= */

export default function ValentineApp() {

    const [page, setPage] = useState("start");
    // start → home → game

    useEffect(() => {
        emailjs.init("aEbujbuY5ZtX1sDQq");
    }, []);


    return (
        <div className="valentine-container">

            {/* Hearts Background */}
            <div className="hearts-bg">
                <div className="heart x1" />
                <div className="heart x2" />
                <div className="heart x3" />
                <div className="heart x4" />
                <div className="heart x5" />
            </div>


            <div className="app-content">

                {page === "start" && (
                    <StartPage onStart={() => setPage("home")} />
                )}

                {page === "home" && (
                    <HomePage onYes={() => setPage("game")} />
                )}

                {page === "game" && (
                    <GamePage />
                )}

            </div>

            <style>{styles}</style>

        </div>
    );
}



/* ================= START PAGE ================= */

function StartPage({ onStart }) {

    return (
        <div
            className="start-page"
            onClick={onStart}
            onTouchStart={onStart}
        >
            <h1>💖 Tap Anywhere to Start 💖</h1>
            <p>Enable sound & begin ✨</p>
        </div>
    );
}



/* ================= HOME PAGE ================= */

function HomePage({ onYes }) {

    const [pos, setPos] = useState({ x: 0, y: 0 });

    const btnRef = useRef(null);
    const yesRef = useRef(null);


    const soundUnlocked = useRef(false);

    const noSound = useRef(null);
    const yesSound = useRef(null);


    /* ================= AUDIO INIT ================= */

    useEffect(() => {

        // NO sound
        const noAudio = new Audio("/sounds/no.mp3");
        noAudio.volume = 0.6;
        noAudio.muted = true;

        // YES hover sound
        const yesAudio = new Audio("/sounds/yes-hover.mp3");
        yesAudio.volume = 0.6;
        yesAudio.muted = true;

        noSound.current = noAudio;
        yesSound.current = yesAudio;


        // Unlock on first user interaction
        const unlock = async () => {

            if (soundUnlocked.current) return;

            try {

                // Unlock NO
                await noSound.current.play();
                noSound.current.pause();
                noSound.current.currentTime = 0;
                noSound.current.muted = false;

                // Unlock YES
                await yesSound.current.play();
                yesSound.current.pause();
                yesSound.current.currentTime = 0;
                yesSound.current.muted = false;

                soundUnlocked.current = true;

                console.log("🔊 Audio unlocked");

            } catch (e) {}

            document.removeEventListener("click", unlock);
            document.removeEventListener("touchstart", unlock);
            document.removeEventListener("keydown", unlock);
        };


        document.addEventListener("click", unlock);
        document.addEventListener("touchstart", unlock);
        document.addEventListener("keydown", unlock);


        return () => {
            document.removeEventListener("click", unlock);
            document.removeEventListener("touchstart", unlock);
            document.removeEventListener("keydown", unlock);
        };

    }, []);



    /* ================= PLAY YES SOUND ================= */

    const playYesSound = () => {

        if (yesSound.current && soundUnlocked.current) {

            yesSound.current.currentTime = 0;

            yesSound.current.play().catch(() => {});
        }
    };

    const stopYesSound = () => {

        if (yesSound.current) {

            yesSound.current.pause();
            yesSound.current.currentTime = 0;
        }
    };


    /* ================= MOVE NO ================= */

    const move = () => {

        const btn = btnRef.current;
        const yesBtn = yesRef.current;

        if (!btn || !yesBtn) return;


        // Play NO sound
        if (noSound.current && soundUnlocked.current) {
            noSound.current.currentTime = 0;
            noSound.current.play().catch(() => {});
        }


        const noRect = btn.getBoundingClientRect();
        const yesRect = yesBtn.getBoundingClientRect();

        const padding = 20; // gap between buttons

        const maxX = window.innerWidth - noRect.width - padding;
        const maxY = window.innerHeight - noRect.height - padding;


        let x, y;
        let safe = false;


        // Try until safe position found
        while (!safe) {

            x = Math.random() * maxX;
            y = Math.random() * maxY;


            const newRect = {
                left: x,
                right: x + noRect.width,
                top: y,
                bottom: y + noRect.height,
            };


            // Check overlap
            const overlap =
                newRect.right + padding > yesRect.left &&
                newRect.left - padding < yesRect.right &&
                newRect.bottom + padding > yesRect.top &&
                newRect.top - padding < yesRect.bottom;


            if (!overlap) safe = true;
        }


        // Convert to transform offset
        const centerX = window.innerWidth / 2;
        const centerY = window.innerHeight / 2;

        const offsetX = x - centerX + noRect.width / 2;
        const offsetY = y - centerY + noRect.height / 2;

        setPos({ x: offsetX, y: offsetY });
    };




    /* ================= UI ================= */

    return (
        <div className="home-page">

            <h1 className="title">
                Will you be my Valentine? 💝
            </h1>


            {/* YES BUTTON */}

            <button
                ref={yesRef}
                className="brutalist-button yes-brutal"
                onClick={onYes}

                onMouseEnter={playYesSound}
                onMouseLeave={stopYesSound}

                onTouchStart={playYesSound}
                onTouchEnd={stopYesSound}
            >


            <div className="yes-content">

          <span className="btn-text">
            YES 💖
          </span>

                    <span className="btn-subtext">
            Don't be shy 😉
          </span>

                </div>

            </button>



            {/* NO BUTTON */}

            <button
                ref={btnRef}
                className="brutalist-button no-brutal"
                onMouseEnter={move}
                onClick={move}
                onTouchStart={move}
                style={{
                    transform: `translate(${pos.x}px, ${pos.y}px)`
                }}
            >
        <span className="btn-text">
          NO 😜
        </span>
            </button>

        </div>
    );
}



/* ================= GAME PAGE ================= */

function GamePage() {

    const [started, setStarted] = useState(false);

    const iframeRef = useRef(null);
    const [key, setKey] = useState(0);

    const isMobile =
        window.matchMedia("(pointer: coarse)").matches;


    /* Start */

    const startGame = () => {

        setStarted(true);
        setKey(k => k + 1);

        setTimeout(() => {
            iframeRef.current?.focus();
        }, 200);
    };


    /* Retry */

    const retry = (e) => {

        const btn = e.currentTarget;

        btn.disabled = true;

        setTimeout(() => {
            btn.disabled = false;
        }, 50);

        setKey(k => k + 1);

        setTimeout(() => {
            iframeRef.current?.focus();
        }, 200);
    };


    return (
        <div className="game-page">


            {!started && (

                <button
                    className="brutalist-button no-brutal"
                    onClick={startGame}
                >
                    ▶ Start Game
                </button>

            )}


            {started && (

                <>

                    <div className="game-frame">

                        <iframe
                            key={key}
                            ref={iframeRef}
                            src="/dino.html"
                            title="Game"
                        />

                    </div>


                    <button
                        className="brutalist-button no-brutal"
                        onClick={retry}
                    >
                        🔄 Retry
                    </button>

                </>

            )}


            <p className="hint">

                {!started
                    ? "If you are bored, press Start 😄"
                    : isMobile
                        ? "Tap = Jump | Swipe ↓ = Duck 📱"
                        : "SPACE = Jump | ↓ = Duck 💻"
                }

            </p>

        </div>
    );
}



